"    const printEnabled = !!business?.business_details?.settings?.print_upi_qr;
    if (printEnabled) {
      try {
        const payeeName = business?.business_name || business?.name || posSettings.receiptHeader || 'SHAHE TEHZEEB RESTAURANT';
        let upiUri = '';
        let displayUpiId = '';
        let brandLabel = '';

        const activeEntry = (backendQrs || []).find(e => String(e.id) === String(posSettings.activeStaticUpiId));
        if (activeEntry) {
          displayUpiId = activeEntry.upi_id;
          brandLabel = activeEntry.name || '';

          const isUrl = activeEntry.upi_id.startsWith('http://') || activeEntry.upi_id.startsWith('https://') || activeEntry.upi_id.startsWith('upi://');
          if (isUrl) {
            upiUri = activeEntry.upi_id;
          } else if (posSettings.qrMode === 'dynamic') {
            let upiAmount = 0;
            if (isBookingReceipt) {
              upiAmount = parseFloat(advancePaid);
            } else if (isSettlement) {
              upiAmount = parseFloat(remainingBalance);
            } else {
              upiAmount = parseFloat(order.total_price || 0);
            }
            upiUri = `upi://pay?pa=${activeEntry.upi_id}&pn=${encodeURIComponent(payeeName)}&am=${upiAmount.toFixed(2)}&cu=INR`;
          } else {
            upiUri = `upi://pay?pa=${activeEntry.upi_id}&pn=${encodeURIComponent(payeeName)}&cu=INR`;
          }
        }"

